def rep(h, old, new, tag, count=1):
    if old not in h:
        raise SystemExit(f"[{tag}] НЕ НАЙДЕН якорь:\n{old[:120]}")
    return h.replace(old, new) if count == 0 else h.replace(old, new, count)

