def build(slug, title, desc, name, herostats, pbox_dur, intro, keyfact, prog,
          mapstops, mapcap, sec1, sec2, faqv, incl, tip, pract, faq_schema):
    h = base
    h = rep(h, E_SLUG, slug, "slug", 0)
    h = rep(h, E_TITLE, title, "title", 0)
    h = rep(h, E_DESC, desc, "desc", 0)
    h = rep(h, E_NAME, name, "name", 0)
    h = rep(h, E_HEROSTATS, herostats, "herostats")
    h = rep(h, E_PBOX_DUR, pbox_dur, "pbox_dur")
    h = rep(h, E_INTRO, intro, "intro")
    h = rep(h, E_KEYFACT, keyfact, "keyfact")
    h = rep(h, E_PROG, prog, "prog")
    h = rep(h, E_MAPSTOPS, mapstops, "mapstops")
    h = rep(h, E_MAPCAP, mapcap, "mapcap")
    h = rep(h, E_SEC1, sec1, "sec1")
    h = rep(h, E_SEC2, sec2, "sec2")
    h = rep(h, E_FAQV, faqv, "faqv")
    h = rep(h, E_INCL, incl, "incl")
    h = rep(h, E_TIP, tip, "tip")
    h = rep(h, E_PRACT, pract, "pract")
    # FAQ schema (одной строкой в head)
    h = rep(h, E_FAQ_SCHEMA, faq_schema, "faq_schema")
    # цена 350 -> 500 (везде, что не переписали блоками)
    h = h.replace("350", "500")
    _img = "truso-tour-600" if "truso" in slug else ("gveleti-hike-600" if "gveleti" in slug else "juta-chaukhi-hike-600")
    h = h.replace("kazbegi-tour-600", _img)
    return h

